import { useState, useCallback } from "react";
import { StatusDot } from "@/shared/ui/feedback/StatusDot";
import { InlineError } from "@/shared/ui/feedback/InlineError";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";
import { Chip } from "@/shared/ui/data/Chip";
import { Card } from "@/shared/ui/data/Card";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Button } from "@/shared/ui/controls/Button";

// Vendored verbatim from `@/shared/lib/core/diagnostics` — pure (no Tauri/glob), safe to keep as-is.
function consequenceFor(name) {
  switch (name) {
    case "Git Bash":
      return { severity: "critical", consequence: "Console sessions can't launch — Git Bash is the shell that runs agents on Windows. Install Git for Windows, then relaunch." };
    case "claude":
      return { severity: "critical", consequence: "Agents can't run — the `claude` CLI is what every console session executes. Install it, then relaunch." };
    case "git":
      return { severity: "critical", consequence: "Repository operations fail — agents can't clone, commit, or create worktrees without `git`." };
    case "gh":
      return { severity: "warning", consequence: "Agents can't open pull requests — install the GitHub CLI (`gh`) to enable PR creation and review." };
    case "gh auth":
      return { severity: "warning", consequence: "`gh` is installed but not authenticated — set `GH_TOKEN` or run `gh auth login` so agents can push and open PRs." };
    default:
      return { severity: "critical", consequence: "This prerequisite is required for agents to run." };
  }
}
function interpretDiagnostics(prereqs) {
  const verdicts = prereqs.map((p) => {
    if (p.found) return { ...p, ok: true, severity: "warning", consequence: "" };
    const { severity, consequence } = consequenceFor(p.name);
    return { ...p, ok: false, severity, consequence };
  });
  const missing = verdicts.filter((v) => !v.ok);
  const allOk = missing.length === 0;
  const worst = allOk ? null : missing.some((m) => m.severity === "critical") ? "critical" : "warning";
  let headline;
  if (allOk) headline = "All prerequisites satisfied.";
  else {
    const names = missing.map((m) => m.name).join(", ");
    const noun = missing.length === 1 ? "prerequisite" : "prerequisites";
    headline = `${missing.length} ${noun} need attention: ${names}.`;
  }
  return { prereqs: verdicts, allOk, worst, headline };
}
// Sample probe result standing in for the real Tauri `invoke("preflight", …)` call.
const SAMPLE_PREREQS = [
  { name: "Git Bash", found: true, version: "2.45.1", path: "C:\\Program Files\\Git\\bin\\bash.exe", hint: "" },
  { name: "claude", found: true, version: "1.2.0", path: "C:\\Users\\dev\\.local\\bin\\claude.exe", hint: "" },
  { name: "git", found: true, version: "2.45.1", path: "C:\\Program Files\\Git\\bin\\git.exe", hint: "" },
  { name: "gh", found: false, version: null, path: null, hint: "Install from https://cli.github.com" },
  { name: "gh auth", found: false, version: null, path: null, hint: "Run gh auth login" },
];

const SEVERITY_COLOR = {
  critical: "var(--danger)",
  warning: "#e5c07b",
  ok: "var(--success)",
};
function firstUrl(text) {
  const m = text.match(/https?:\/\/\S+/);
  return m ? m[0] : null;
}
function PrereqRow({ verdict, alt }) {
  const url = verdict.ok ? null : firstUrl(verdict.hint);
  const dotColor = verdict.ok ? SEVERITY_COLOR.ok : SEVERITY_COLOR[verdict.severity];
  return (
    <Row align="start" gap={12} style={{
      padding: "12px 14px",
      background: alt ? "var(--bg-panel)" : "var(--bg-elev)",
    }}>
      <Box style={{ paddingTop: 3 }}>
        <StatusDot
          color={dotColor}
          size={9}
          title={verdict.ok ? "found" : verdict.severity}
          style={{ boxShadow: `0 0 0 3px color-mix(in oklch, ${dotColor}, transparent 82%)` }}
        />
      </Box>
      <Box style={{ flex: 1, minWidth: 0 }}>
        <Row gap={8} wrap>
          <Text mono size={12.5} style={{ color: "var(--fg)" }}>{verdict.name}</Text>
          {verdict.ok ? (
            <Chip tone="success" style={{ fontSize: 9.5 }}><StatusDot style={{ marginRight: 4 }} />found</Chip>
          ) : (
            <Chip style={{ fontSize: 9.5, color: SEVERITY_COLOR[verdict.severity], borderColor: SEVERITY_COLOR[verdict.severity] }}>
              <StatusDot style={{ marginRight: 4 }} />{verdict.severity === "critical" ? "missing" : "attention"}
            </Chip>
          )}
          {verdict.version && (
            <Text mono size={10.5} tone="muted">{verdict.version}</Text>
          )}
        </Row>
        {verdict.ok ? (
          verdict.path && (
            <Text as="div" mono size={10} tone="dim" style={{ marginTop: 3, wordBreak: "break-all" }}>
              {verdict.path}
            </Text>
          )
        ) : (
          <Text as="div" size={11.5} tone="muted" style={{ marginTop: 4, lineHeight: 1.55 }}>
            {verdict.consequence}
            {url && (
              <>
                {" "}
                <a href={url} className="mono" style={{ color: "var(--accent)", cursor: "pointer", fontSize: 10.5 }}>
                  {url.replace(/^https?:\/\//, "")} ↗
                </a>
              </>
            )}
          </Text>
        )}
      </Box>
    </Row>
  );
}
export function DiagnosticsCard() {
  const [report, setReport] = useState(() => interpretDiagnostics(SAMPLE_PREREQS));
  const [takenAt, setTakenAt] = useState(() => Date.now());
  const [running, setRunning] = useState(false);
  const [error] = useState(null);

  const runProbe = useCallback(async () => {
    setRunning(true);
    setTimeout(() => {
      setReport(interpretDiagnostics(SAMPLE_PREREQS));
      setTakenAt(Date.now());
      setRunning(false);
    }, 400);
  }, []);

  const banner = report
    ? report.allOk
      ? { color: SEVERITY_COLOR.ok, text: report.headline }
      : { color: SEVERITY_COLOR[report.worst ?? "warning"], text: report.headline }
    : null;

  return (
    <Card style={{ padding: 0, overflow: "hidden" }}>
      <Row gap={12} style={{
        padding: "12px 14px",
        borderBottom: "1px solid var(--border-soft)", background: "var(--bg-elev)",
      }}>
        {banner && (
          <StatusDot
            color={banner.color}
            size={9}
            style={{ boxShadow: `0 0 0 3px color-mix(in oklch, ${banner.color}, transparent 82%)` }}
          />
        )}
        <Text mono size={12} style={{ flex: 1, color: "var(--fg)" }}>
          {banner ? banner.text : running ? "Checking…" : "Not checked yet."}
        </Text>
        {takenAt && (
          <Text mono size={10} tone="dim">
            checked {new Date(takenAt).toLocaleTimeString()}
          </Text>
        )}
        <Button variant="ghost" style={{ height: 28, fontSize: 11 }} disabled={running} onClick={() => void runProbe()}>
          {running ? "checking…" : "↺ re-check"}
        </Button>
      </Row>

      {error && (
        <InlineError radius={0} borderFade={100} style={{ borderBottom: "1px solid var(--border-soft)" }}>
          Probe failed: {error}
        </InlineError>
      )}

      {report && report.prereqs.length > 0 ? (
        <Stack gap={1}>
          {report.prereqs.map((v, i) => <PrereqRow key={v.name} verdict={v} alt={i % 2 === 1} />)}
        </Stack>
      ) : !running && !error ? (
        <EmptyState iconVariant="dashed" title="No prerequisite data yet." />
      ) : null}
    </Card>
  );
}
